-- Name: sync_application_current_state(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_application_current_state() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN

    UPDATE public.applications
    SET current_state_id = NEW.to_state_id
    WHERE application_id = NEW.application_id;

    RETURN NEW;
END;
$$;


